@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (isLoading)
{
    <p><em>Loading tasks...</em></p>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger">@errorMessage</div>
}
else
{
    <!-- Summary Stats Bar -->
    <div class="stats-bar">
        <span class="stat-item"><strong>Total:</strong> @filteredTasks.Count</span>
        <span class="stat-item"><strong>To Do:</strong> @ToDoTasks.Count()</span>
        <span class="stat-item"><strong>In Progress:</strong> @InProgressTasks.Count()</span>
        <span class="stat-item"><strong>Done:</strong> @DoneTasks.Count()</span>
        <span class="stat-item stat-overdue"><strong>Overdue:</strong> @filteredTasks.Count(t => t.DueDate < DateTime.Today)</span>
    </div>

    <!-- Search Bar -->
    <div class="search-bar">
        <input type="text" class="form-control" placeholder="Search tasks by title..."
               @bind="searchQuery" @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="board-columns">
        <!-- To Do Column -->
        <div class="board-column">
            <div class="column-header">
                <h3>To Do <span class="badge bg-secondary">@ToDoTasks.Count()</span></h3>
            </div>
            <div class="column-body">
                @foreach (var task in ToDoTasks)
                {
                    <div class="task-card">
                        <div class="task-title">@task.Title</div>
                        <div class="task-assignee">@task.Assignee</div>
                        <span class="badge priority-@task.Priority.ToLower()">@task.Priority</span>
                        <div class="task-due">@task.DueDate.ToString("MMM dd")</div>
                        <div class="task-actions">
                            <button class="btn btn-sm btn-outline-primary" @onclick="() => MoveRight(task)">Move Right &rarr;</button>
                        </div>
                    </div>
                }
            </div>
            @if (showAddForm == "To Do")
            {
                <div class="add-task-form">
                    <input type="text" class="form-control mb-1" placeholder="Title" @bind="newTitle" />
                    <input type="text" class="form-control mb-1" placeholder="Assignee" @bind="newAssignee" />
                    <select class="form-select mb-1" @bind="newPriority">
                        <option value="High">High</option>
                        <option value="Medium">Medium</option>
                        <option value="Low">Low</option>
                    </select>
                    <input type="date" class="form-control mb-1" @bind="newDueDate" />
                    <div class="d-flex gap-1">
                        <button class="btn btn-sm btn-success" @onclick="() => SaveTask(\"To Do\")">Save</button>
                        <button class="btn btn-sm btn-secondary" @onclick="CancelAdd">Cancel</button>
                    </div>
                </div>
            }
            else
            {
                <button class="btn btn-sm btn-outline-secondary mt-2" @onclick="() => ShowAddForm(\"To Do\")">+ Add Task</button>
            }
        </div>

        <!-- In Progress Column -->
        <div class="board-column">
            <div class="column-header">
                <h3>In Progress <span class="badge bg-secondary">@InProgressTasks.Count()</span></h3>
            </div>
            <div class="column-body">
                @foreach (var task in InProgressTasks)
                {
                    <div class="task-card">
                        <div class="task-title">@task.Title</div>
                        <div class="task-assignee">@task.Assignee</div>
                        <span class="badge priority-@task.Priority.ToLower()">@task.Priority</span>
                        <div class="task-due">@task.DueDate.ToString("MMM dd")</div>
                        <div class="task-actions">
                            <button class="btn btn-sm btn-outline-primary" @onclick="() => MoveLeft(task)">&larr; Move Left</button>
                            <button class="btn btn-sm btn-outline-primary" @onclick="() => MoveRight(task)">Move Right &rarr;</button>
                        </div>
                    </div>
                }
            </div>
            @if (showAddForm == "In Progress")
            {
                <div class="add-task-form">
                    <input type="text" class="form-control mb-1" placeholder="Title" @bind="newTitle" />
                    <input type="text" class="form-control mb-1" placeholder="Assignee" @bind="newAssignee" />
                    <select class="form-select mb-1" @bind="newPriority">
                        <option value="High">High</option>
                        <option value="Medium">Medium</option>
                        <option value="Low">Low</option>
                    </select>
                    <input type="date" class="form-control mb-1" @bind="newDueDate" />
                    <div class="d-flex gap-1">
                        <button class="btn btn-sm btn-success" @onclick="() => SaveTask(\"In Progress\")">Save</button>
                        <button class="btn btn-sm btn-secondary" @onclick="CancelAdd">Cancel</button>
                    </div>
                </div>
            }
            else
            {
                <button class="btn btn-sm btn-outline-secondary mt-2" @onclick="() => ShowAddForm(\"In Progress\")">+ Add Task</button>
            }
        </div>

        <!-- Done Column -->
        <div class="board-column">
            <div class="column-header">
                <h3>Done <span class="badge bg-secondary">@DoneTasks.Count()</span></h3>
            </div>
            <div class="column-body">
                @foreach (var task in DoneTasks)
                {
                    <div class="task-card">
                        <div class="task-title">@task.Title</div>
                        <div class="task-assignee">@task.Assignee</div>
                        <span class="badge priority-@task.Priority.ToLower()">@task.Priority</span>
                        <div class="task-due">@task.DueDate.ToString("MMM dd")</div>
                        <div class="task-actions">
                            <button class="btn btn-sm btn-outline-primary" @onclick="() => MoveLeft(task)">&larr; Move Left</button>
                        </div>
                    </div>
                }
            </div>
            @if (showAddForm == "Done")
            {
                <div class="add-task-form">
                    <input type="text" class="form-control mb-1" placeholder="Title" @bind="newTitle" />
                    <input type="text" class="form-control mb-1" placeholder="Assignee" @bind="newAssignee" />
                    <select class="form-select mb-1" @bind="newPriority">
                        <option value="High">High</option>
                        <option value="Medium">Medium</option>
                        <option value="Low">Low</option>
                    </select>
                    <input type="date" class="form-control mb-1" @bind="newDueDate" />
                    <div class="d-flex gap-1">
                        <button class="btn btn-sm btn-success" @onclick="() => SaveTask(\"Done\")">Save</button>
                        <button class="btn btn-sm btn-secondary" @onclick="CancelAdd">Cancel</button>
                    </div>
                </div>
            }
            else
            {
                <button class="btn btn-sm btn-outline-secondary mt-2" @onclick="() => ShowAddForm(\"Done\")">+ Add Task</button>
            }
        </div>
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private bool isLoading = true;
    private string? errorMessage;
    private string searchQuery = string.Empty;

    // Add task form state
    private string? showAddForm;
    private string newTitle = string.Empty;
    private string newAssignee = string.Empty;
    private string newPriority = "Medium";
    private DateTime newDueDate = DateTime.Today;

    private List<TaskItem> filteredTasks => string.IsNullOrWhiteSpace(searchQuery)
        ? allTasks
        : allTasks.Where(t => t.Title.Contains(searchQuery, StringComparison.OrdinalIgnoreCase)).ToList();

    private IEnumerable<TaskItem> ToDoTasks => filteredTasks.Where(t => t.Status == "To Do");
    private IEnumerable<TaskItem> InProgressTasks => filteredTasks.Where(t => t.Status == "In Progress");
    private IEnumerable<TaskItem> DoneTasks => filteredTasks.Where(t => t.Status == "Done");

    private static readonly string[] Columns = { "To Do", "In Progress", "Done" };

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task MoveLeft(TaskItem task)
    {
        var currentIndex = Array.IndexOf(Columns, task.Status);
        if (currentIndex > 0)
        {
            var newStatus = Columns[currentIndex - 1];
            try
            {
                await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
                var index = allTasks.FindIndex(t => t.Id == task.Id);
                if (index >= 0)
                    allTasks[index] = task with { Status = newStatus };
            }
            catch (Exception ex)
            {
                errorMessage = $"Failed to move task: {ex.Message}";
            }
        }
    }

    private async Task MoveRight(TaskItem task)
    {
        var currentIndex = Array.IndexOf(Columns, task.Status);
        if (currentIndex < Columns.Length - 1)
        {
            var newStatus = Columns[currentIndex + 1];
            try
            {
                await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
                var index = allTasks.FindIndex(t => t.Id == task.Id);
                if (index >= 0)
                    allTasks[index] = task with { Status = newStatus };
            }
            catch (Exception ex)
            {
                errorMessage = $"Failed to move task: {ex.Message}";
            }
        }
    }

    private void ShowAddForm(string column)
    {
        showAddForm = column;
        newTitle = string.Empty;
        newAssignee = string.Empty;
        newPriority = "Medium";
        newDueDate = DateTime.Today;
    }

    private void CancelAdd()
    {
        showAddForm = null;
    }

    private async Task SaveTask(string status)
    {
        if (string.IsNullOrWhiteSpace(newTitle))
            return;

        try
        {
            var created = await TaskService.CreateTaskAsync(newTitle, newAssignee, newPriority, newDueDate);
            // CreateTaskAsync creates with default status; update if column differs
            if (created.Status != status)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, status);
                created = created with { Status = status };
            }
            allTasks.Add(created);
            showAddForm = null;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

